#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Interval {
    pub min: i32,
    pub max: i32,
}

impl Interval {
    pub fn new(min: i32, max: i32) -> Self {
        assert!(min < max, "invalid interval: min must be < max");
        Self { min, max }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ChebyshevPoly {
    pub coef: Vec<i32>,
    pub domain: Interval,
    pub window: Interval,
}

pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    assert!(!coef.is_empty(), "coefficients must be non-empty");

    let coef_i32: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    let domain = Interval::new(-1, 1);
    let window = Interval::new(-1, 1);

    ChebyshevPoly {
        coef: coef_i32,
        domain,
        window,
    }
}